        src = _safe_join(data_dir, rel)
        dst = _safe_join(old_root, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(src, dst)
        # 复制后立即按落盘字节登记长度/哈希，与回滚期重新核对使用同一口径。
